<script setup lang="ts">
import {ref,watch} from 'vue'; import {apiError} from './apiError';
const props=defineProps<{projectId:string;section:string}>(); const busy=ref(false),error=ref(''),message=ref(''),versions=ref<any[]>([]),selectedVersion=ref<any>(null);
const geography=ref({coordinate_system:'WGS84',region:'',longitude:null as number|null,latitude:null as number|null,source:'',notes:''});
const disaster=ref({event_id:'',hazard_type:'',start_time:'',end_time:'',intensity:null as number|null,intensity_unit:'',affected_devices:'',source:'',verified:false,notes:''});
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function read(){if(!props.projectId)return;busy.value=true;error.value='';try{const d=await api('/api/drafts/'+encodeURIComponent('地理与灾害')+'?project_id='+encodeURIComponent(props.projectId));Object.assign(geography.value,d.values?.geography||{});Object.assign(disaster.value,d.values?.disaster||{});versions.value=await api('/api/engineering/projects/'+props.projectId+'/versions')}catch(e){error.value=String(e)}finally{busy.value=false}}
watch(()=>props.projectId,read,{immediate:true}); async function inspectVersion(revision:number){try{selectedVersion.value=await api('/api/engineering/projects/'+props.projectId+'/versions/'+revision)}catch(e){error.value=String(e)}} async function save(){busy.value=true;try{const d=await api('/api/drafts/地理与灾害?project_id='+encodeURIComponent(props.projectId),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:{geography:geography.value,disaster:disaster.value}})});message.value='已保存本机数据库草稿 · '+d.updated}catch(e){error.value=String(e)}finally{busy.value=false}}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({project_id:props.projectId,geography:geography.value,disaster:disaster.value,status:'draft'},null,2)],{type:'application/json'}));a.download='地理与灾害草稿.json';a.click()}
async function upload(event:Event){const input=event.target as HTMLInputElement;error.value='';try{const file=input.files?.[0];if(!file)return;if(file.size>1000000)throw Error('地理与灾害JSON不得超过1MB');const d=JSON.parse(await file.text());if(!d||typeof d!=='object'||!d.geography||!d.disaster)throw Error('文件须包含geography和disaster对象');Object.assign(geography.value,d.geography);Object.assign(disaster.value,d.disaster);message.value='已载入本地草稿，请检查后保存；尚未覆盖数据库记录。'}catch(e){error.value=String(e)}finally{input.value=''}}
</script>
<template><article v-if="section==='地理与灾害'"><h3>地理与历史灾害数据</h3><p>坐标、灾害事件和设备影响必须填写来源；未核实记录不会自动进入故障概率或计算模型。</p><p v-if="error" class="error">{{error}}</p><p v-if="message" class="notice">{{message}}</p><div class="grid"><article><h3>区域与坐标</h3><label class="field">区域<input v-model="geography.region"></label><label class="field">坐标系<input v-model="geography.coordinate_system"></label><label class="field">经度<input type="number" step="any" v-model.number="geography.longitude"></label><label class="field">纬度<input type="number" step="any" v-model.number="geography.latitude"></label><label class="field">来源<input v-model="geography.source"></label><label>备注<textarea v-model="geography.notes"></textarea></label></article><article><h3>历史灾害事件</h3><label class="field">事件编号<input v-model="disaster.event_id"></label><label class="field">灾害类型<input v-model="disaster.hazard_type"></label><label class="field">开始时间<input type="datetime-local" v-model="disaster.start_time"></label><label class="field">结束时间<input type="datetime-local" v-model="disaster.end_time"></label><label class="field">强度<input type="number" step="any" v-model.number="disaster.intensity"></label><label class="field">强度单位<input v-model="disaster.intensity_unit"></label><label class="field">受影响设备ID<input v-model="disaster.affected_devices"></label><label class="field">来源<input v-model="disaster.source"></label><label><input type="checkbox" v-model="disaster.verified"> 已由项目组核实</label><label>备注<textarea v-model="disaster.notes"></textarea></label></article></div><div class="actions"><button @click="save" :disabled="busy">保存地理与灾害草稿</button><button @click="download">导出 JSON</button><label class="button">导入 JSON<input type="file" accept=".json" hidden @change="upload"></label></div></article><article v-else><h3>数据版本管理</h3><p>工程台账采用递增版本，保存会校验当前工程版本并保留历史快照。</p><p v-if="error" class="error">{{error}}</p><div class="scroll"><table><tr><th>版本</th><th>工程名称</th><th>区域</th><th>状态</th><th>操作</th></tr><tr v-for="v in versions" :key="v.revision"><td>v{{v.revision}}</td><td>{{v.name}}</td><td>{{v.region||'未填写'}}</td><td>{{v.revision===versions[0]?.revision?'当前':'历史快照'}}</td><td><button @click="inspectVersion(v.revision)">查看快照</button></td></tr></table></div><article v-if="selectedVersion"><h3>只读快照 v{{selectedVersion.revision}}</h3><pre>{{JSON.stringify(selectedVersion,null,2)}}</pre></article><p class="notice">计算任务中的输入快照不会随当前工程修改而改变。</p><button @click="read" :disabled="busy">刷新版本列表</button></article></template>
<style scoped>.field{display:flex;justify-content:space-between;gap:12px;margin:10px 0}.field input{width:58%;padding:7px}textarea{width:100%;min-height:70px;padding:8px}.actions{display:flex;gap:10px}.scroll{max-height:360px;overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #e2eded}</style>



